	defer rows.Close()
	found := map[string]*types.TransferGroup{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := transferGroupKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.TransferGroup, len(inputs))
	for i, input := range inputs {
		text, _ := transferGroupKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the TransferGroup row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
